def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False
    # Check that the string contains exactly two distinct characters
    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False
    # Check that characters alternate
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False
    return True
